9	// R20 "If recording fails after the upload, the file must not be left behind." Every case uploads a
10	// real slip with the staff token (the UI path, D22), then makes POST /api/leases/:leaseId/payments fail,
11	// and checks storage.objects with pg (postgres) that the object is gone. R44: a failing request must never
12	// delete a slip in ANOTHER org's folder (the server deletes only inside the caller's own org folder).
13	
14	const BUCKET = "payment-slips";
15	// 1x1 transparent PNG.
16	const PNG = Buffer.from(
17	  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
18	  "base64",
19	);
20	const LEASE = { startDate: "2026-01-01", endDate: "2026-06-30", monthlyRentSen: 100000, depositSen: 0 };
21	const RECEIVED_AT = "2026-02-01T10:00:00+08:00";
22	
23	let A: FixtureOrg;
24	let B: FixtureOrg;
25	const created = new Set<string>();
26	
27	async function objectExists(name: string): Promise<boolean> {
28	  const rows = await sql("select 1 from storage.objects where bucket_id = $1 and name = $2", [BUCKET, name]);
29	  return rows.length === 1;
30	}
31	
32	/** Uploads a PNG slip as `org`'s staff into `<org>/<org.lease>/<uuid>.png` and proves it landed. */
33	async function uploadPng(org: FixtureOrg): Promise<string> {
34	  const path = `${org.orgId}/${org.lease!.id}/${randomUUID()}.png`;
35	  created.add(path);
36	  const { error } = await userClient(org.tokens.staff)
37	    .storage.from(BUCKET)
38	    .upload(path, PNG, { contentType: "image/png", upsert: false });
39	  expect(error).toBeNull();
40	  expect(await objectExists(path)).toBe(true);
41	  return path;
42	}
43	
44	const body = (slipPath: string, receivedAt = RECEIVED_AT) => ({
45	  amountSen: 1000,
46	  method: "bank_transfer",
47	  receivedAt,
48	  slipPath,
49	});
50	
51	function expectErrorBody(res: { body: unknown }) {
52	  expect(errorBody.safeParse(res.body).success).toBe(true);
53	}
54	
55	beforeAll(async () => {
56	  [A, B] = await Promise.all([createFixtureOrg({ lease: LEASE }), createFixtureOrg({ lease: LEASE })]);
57	});
58	
59	afterAll(async () => {
60	  if (created.size) await adminClient().storage.from(BUCKET).remove([...created]);
61	  await closePool();
62	});
