64	describe("R20 R44 POST /api/leases/:leaseId/payments failing after the upload removes the caller's slip", () => {
65	  it("nonexistent (well-formed) lease id -> 404 and the slip is gone", async () => {
66	    const path = await uploadPng(A);
67	    const res = await api(A.tokens.staff).post(`/api/leases/${randomUUID()}/payments`, body(path));
68	    expect(res.status).toBe(404);
69	    expectErrorBody(res);
70	    expect(await objectExists(path)).toBe(false);
71	  });
72	
73	  it("another org's lease -> 404 and the slip (in the caller's own org folder) is gone", async () => {
74	    const path = await uploadPng(A);
75	    const res = await api(A.tokens.staff).post(`/api/leases/${B.lease!.id}/payments`, body(path));
76	    expect(res.status).toBe(404);
77	    expectErrorBody(res);
78	    expect(await objectExists(path)).toBe(false);
79	  });
80	
81	  it("own lease, receivedAt without an offset -> 400 and the slip is gone", async () => {
82	    const path = await uploadPng(A);
83	    const res = await api(A.tokens.staff).post(`/api/leases/${A.lease!.id}/payments`, body(path, "2026-02-01T10:00:00"));
84	    expect(res.status).toBe(400);
85	    expectErrorBody(res);
86	    expect(await objectExists(path)).toBe(false);
87	  });
88	
89	  // Not recoverable: with an unparseable body the server cannot learn slipPath, so it has nothing to
90	  // delete. Cleaning such orphans needs a sweeper (objects with no payments.slip_path), which SPEC does not have.
91	  // So there is no test for that case; the next test pins that such a request never deletes anything.
92	
93	  it("malformed JSON body -> 400 JSON and never deletes anything", async () => {
94	    const path = await uploadPng(A);
95	    const res = await api(A.tokens.staff).post(`/api/leases/${A.lease!.id}/payments`, `{"slipPath":"${path}",`);
96	    expect(res.status).toBe(400);
97	    expectErrorBody(res);
98	    expect(await objectExists(path)).toBe(true);
99	  });
100	});
